int main(){auto raw=readbytes("study_roots.bin"),expected=readbytes("study_expected_u64.bin");unsigned P=raw.size()/16;QueenRoot*roots;unsigned long long*tree,*sol;cudaMalloc(&roots,raw.size());cudaMalloc(&tree,8ull*P);cudaMalloc(&sol,8ull*P);cudaMemcpy(roots,raw.data(),raw.size(),cudaMemcpyHostToDevice);cudaDeviceSynchronize();auto start=std::chrono::steady_clock::now();BP_queens_root_dfs<<<(P+127)/128,128>>>(15,P,7,roots,tree,sol);auto status=cudaDeviceSynchronize();double seconds=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();std::vector<unsigned long long>out(2ull*P);cudaMemcpy(out.data(),tree,8ull*P,cudaMemcpyDeviceToHost);cudaMemcpy(out.data()+P,sol,8ull*P,cudaMemcpyDeviceToHost);bool exact=expected.size()==16ull*P&&memcmp(out.data(),expected.data(),expected.size())==0;printf("NQUEEN_DIAGNOSTIC prefixes=%u N=15 depth=7 one_launch_seconds=%.9g cuda_status=%d full_per_prefix_exact=%d cold_native_module_loading_may_be_included=1 primary_series=0\n",P,seconds,int(status),int(exact));return status==cudaSuccess&&exact?0:1;}
